import{_ as c}from"./chunks/ArticleMetadata.Xa7L4Afm.js";import{_ as l,D as i,o,c as n,I as p,w as _,k as r,a as h,R as m,b as u,e as f}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const N=JSON.parse('{"title":"插件扩展与安全边界","description":"","frontmatter":{"title":"插件扩展与安全边界","showArticleMetadata":false,"showComment":false},"headers":[],"relativePath":"open-source/01-dsh-mytable/03-插件扩展与安全边界.md","filePath":"open-source/01-dsh-mytable/03-插件扩展与安全边界.md","lastUpdated":1789997903000}'),b={name:"open-source/01-dsh-mytable/03-插件扩展与安全边界.md"},y=r("h1",{id:"插件扩展与安全边界",tabindex:"-1"},[h("插件扩展与安全边界 "),r("a",{class:"header-anchor",href:"#插件扩展与安全边界","aria-label":'Permalink to "插件扩展与安全边界"'},"​")],-1),P=m('<p>工作台既要开放扩展，也要控制本地文件、终端和网页嵌入带来的风险。<code>mytable-service.ts</code> 和服务端路由分别承担了这两部分职责。</p><h2 id="对其他插件开放的注册表" tabindex="-1">对其他插件开放的注册表 <a class="header-anchor" href="#对其他插件开放的注册表" aria-label="Permalink to &quot;对其他插件开放的注册表&quot;">​</a></h2><p>客户端通过 <code>ctx.mytable</code> 暴露两类注册能力：</p><ul><li><code>registerPaneType</code>：注册新的工作台窗口，可以返回 iframe URL，也可以直接挂载 React 节点或 DOM 节点；</li><li><code>registerFileViewer</code>：按扩展名注册文件预览器，并通过优先级决定命中顺序。</li></ul><p>每次注册都会返回 disposer。插件卸载或热更新时，Cordis 可以调用 disposer 清理注册项，避免旧窗口类型残留。注册表还会拒绝空 id、重复 id 和占用内置名称的 id。</p><p>用户可以在设置页禁用某个扩展。禁用后入口从选择器消失，文件预览则回落到内置行为，而不是破坏已有数据。</p><h2 id="本地资源边界" tabindex="-1">本地资源边界 <a class="header-anchor" href="#本地资源边界" aria-label="Permalink to &quot;本地资源边界&quot;">​</a></h2><p>服务端文件接口以会话工作目录为首选边界，并对目录枚举、递归搜索和响应大小设置上限。例如搜索会限制命中数量、扫描数量和深度，同时跳过 <code>node_modules</code>、<code>.git</code>、构建产物与缓存目录。</p><p>这些限制既是性能策略，也是安全策略：一个工作台搜索不应该因为误选磁盘根目录就无限遍历整个文件系统。</p><h2 id="浏览器嵌入策略" tabindex="-1">浏览器嵌入策略 <a class="header-anchor" href="#浏览器嵌入策略" aria-label="Permalink to &quot;浏览器嵌入策略&quot;">​</a></h2><p>浏览器窗格不能假设所有网页都允许 iframe。服务端会探测目标站点的 <code>Content-Security-Policy</code> 与 <code>X-Frame-Options</code>，客户端再据此决定嵌入、外部打开或提示用户。</p><p>远程部署 DSH 时也不应直接把本地端口暴露到公网。仓库文档推荐使用 SSH 端口转发，并提醒额外配置 HTTPS、身份认证、反向代理和可信主机。</p><h2 id="依赖与发布" tabindex="-1">依赖与发布 <a class="header-anchor" href="#依赖与发布" aria-label="Permalink to &quot;依赖与发布&quot;">​</a></h2><p>插件把适配后的 <code>dsh-flowglass</code> 作为打包依赖放进 <code>vendor/</code>，发布包因此不依赖相邻仓库。版本发布采用不可变的 Git 标签和 Release <code>.tgz</code>，可以避免下载地址内容变化后触发 pnpm 缓存完整性问题。</p><p>这套取舍的核心是：让扩展点足够开放，但让高权限能力仍然经过明确的宿主服务、边界检查和可回收的生命周期。</p><p>上一篇：<a href="/open-source/01-dsh-mytable/02-分栏工作区模型">分栏工作区模型</a> · <a href="/open-source/01-dsh-mytable/">返回项目导读</a></p>',16);function k(e,C,S,T,q,x){const d=c,s=i("ClientOnly");return o(),n("div",null,[y,p(s,null,{default:_(()=>{var a,t;return[(((a=e.$frontmatter)==null?void 0:a.aside)??!0)&&(((t=e.$frontmatter)==null?void 0:t.showArticleMetadata)??!0)?(o(),u(d,{key:0,article:e.$frontmatter},null,8,["article"])):f("",!0)]}),_:1}),P])}const $=l(b,[["render",k]]);export{N as __pageData,$ as default};
